#!/usr/bin/bash
# ==== File generated by ./generate_runs.py, do not edit! ====

set -euo pipefail
JLM_PATH="${JLM_PATH:-jlm}"
PARALLEL_TASKS="${PARALLEL_TASKS:-1}"
TMP_STATS_DIR="${TMP_STATS_DIR:-statistics}"
echo "Run started at $(date)" | tee -a "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"
echo "Benchmark checkout:" | tee -a "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"
git rev-parse HEAD | tee -a "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"
git status --porcelain | tee -a "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"
echo "Jlm checkout:" | tee -a "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"
git -C "${JLM_PATH}" rev-parse HEAD | tee -a "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"
git -C "${JLM_PATH}" status --porcelain | tee -a "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"
set -x

if [ -f "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.csv" ]; then
echo "Configuration already done" >> "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"
exit 0
fi


./benchmark.py "--jlm-opt=${JLM_PATH}/build-release/jlm-opt" --llvmbin=/usr/lib/llvm-18/bin --sources=sources/sources.json -j="${PARALLEL_TASKS}" --statsdir="${TMP_STATS_DIR}" --full-spec '--filter=5\d\d\.' --filter=emacs --filter=gdb --filter=ghostscript --filter=sendmail --noStrictAliasing --clangOz --pre-jlm-name clangOz --regionAwareModRef --jlm-name Oz-raw-ip-rcaf-omf-cmf-osf-0 --nullOutput

echo "Done with status code $? at $(date)" >> "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"

echo "Aggregating statistics into single csv" >> "statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.echo"
python3 analysis/aggregate-memstates.py --stats-in="${TMP_STATS_DIR}/Oz-raw-ip-rcaf-omf-cmf-osf-0" --stats-out="statistics-out/Oz-raw-ip-rcaf-omf-cmf-osf-0.csv"

if [ ! -z "${CLEAN_TMP_STATS_DIR+x}" ]; then
rm -rf "${TMP_STATS_DIR}/Oz-raw-ip-rcaf-omf-cmf-osf-0"
fi
